    with self._lock:
        all_records = self._read_sign_sessions(wallet_id)
        if session_id not in all_records:
            return
        del all_records[session_id]
        if all_records:
            self._atomic_write(path, all_records)
        else:
            try:
                os.unlink(path)
            except FileNotFoundError:
                pass

